public class Solution {
  /**
   * Kruskal：排序键打包进 long —— 高 32 位是 (long)w 的有符号值，低 32 位是无符号边号。
   * long 的有符号比较 = 先比高 32 位（w 的有符号序，负权也天然排在最前）、再比低 32 位（边号，保证并列时结果确定）。
   * 因此绝不能再给 w 加 MIN_VALUE 偏移：那会把 w>=0 的位顶到符号位上，序就乱了。
   * 并查集按大小组并 + 迭代 find + 路径压缩；自环被 ru==rv 天然跳过（下面显式 continue 以便归因）。
   */
  public static long mstCost(int n, int[] u, int[] v, int[] w) {
    if (u.length != v.length || u.length != w.length) {
      throw new IllegalArgumentException("edge arrays must be parallel");
    }
    int m = u.length;
    for (int e = 0; e < m; e++) {
      if (u[e] < 0 || u[e] >= n || v[e] < 0 || v[e] >= n) {
        throw new IllegalArgumentException("edge endpoint out of range");
      }
      if (w[e] < 0) throw new IllegalArgumentException("negative edge cost");
    }
    if (n <= 1) return 0L;
    long[] keys = new long[m];
    for (int e = 0; e < m; e++) {
      keys[e] = ((long) w[e] << 32) | (e & 0xffffffffL);
    }
    java.util.Arrays.sort(keys);
    int[] parent = new int[n];
    int[] size = new int[n];
    for (int node = 0; node < n; node++) {
      parent[node] = node;
      size[node] = 1;
    }
    long total = 0L;
    int used = 0;
    for (long key : keys) {
      int e = (int) key;                        // 低 32 位取回原边号
      if (u[e] == v[e]) continue;               // 自环：忽略，不计成本
      int ru = find(parent, u[e]);
      int rv = find(parent, v[e]);
      if (ru == rv) continue;                   // 已连通（重边/环）
      if (size[ru] < size[rv]) {
        int t = ru;
        ru = rv;
        rv = t;
      }
      parent[rv] = ru;
      size[ru] += size[rv];
      total += w[e];                            // long 域累加
      if (++used == n - 1) break;
    }
    return used == n - 1 ? total : -1L;
  }

  static int find(int[] parent, int x) {
    int root = x;
    while (parent[root] != root) root = parent[root];
    while (parent[x] != root) {
      int next = parent[x];
      parent[x] = root;
      x = next;
    }
    return root;
  }
}

