public class Solution {
  // 朴素：用 Integer[] + Comparator 排边（能过，但每条边一个装箱对象），
  // 更致命的是总成本用 int 累加，并且忘了检查"是否真的连通"——不连通时给出一个看似合理的部分成本。
  public static long mstCost(int n, int[] u, int[] v, int[] w) {
    int m = u.length;
    Integer[] idx = new Integer[m];
    for (int e = 0; e < m; e++) idx[e] = e;
    java.util.Arrays.sort(idx, java.util.Comparator.comparingInt(e -> w[e]));
    int[] parent = new int[n];
    for (int node = 0; node < n; node++) parent[node] = node;
    int total = 0;
    for (int e : idx) {
      int ru = find(parent, u[e]);
      int rv = find(parent, v[e]);
      if (ru == rv) continue;
      parent[rv] = ru;
      total += w[e];
    }
    return total;
  }

  static int find(int[] parent, int x) {
    while (parent[x] != x) x = parent[x];
    return x;
  }
}
